// PARTIAL-01 (HPM 2026-10-18) — how much of its own frozen prescription a COMPLETED guided session recorded, with the
// very rules the session used to ask « Terminer quand même ? » (strengthProgress / dhProgress): every prescribed work set
// / pass performed → complete; fewer → partial. Finalisation HPM: endurance (one activity of any duration completes it)
// and recovery (no result at all) only prove the session was closed → null (neutral « Terminée »). Nothing is invented.
// Prescriptions generated by the real engine (test/guidedSessionFakeBackend.prescriptionView).
import { describe, expect, it } from "vitest";
import { guidedRealisationOf } from "./guidedRealisation";
import { prescriptionView } from "../../test/guidedSessionFakeBackend";
import { workItems } from "../guidedSession/strength/strengthSets";
import { mainDrill } from "../guidedSession/dh/dhPasses";
import type { SetResultRow } from "../guidedSession/executionState";
import phys03 from "../../test/fixtures/phys03FinalPrescriptionV2.json";
import { decodeFinalPrescriptionV2 } from "../finalPrescriptionV2/decodeFinalPrescriptionV2";

const result = (prescriptionItemId: string, set_number: number, done = true, id = `${prescriptionItemId}-${set_number}`, supersedes_id: string | null = null): SetResultRow => ({
  id, prescription_item_id: prescriptionItemId, other_exercise_name: null, set_number, done, measure_type: "reps", measure_value: 8, load_kg: null, rpe_actual: null, success: null, supersedes_id,
  occurred_at: "2026-10-20T17:10:00Z", recorded_at: "2026-10-20T17:10:00Z",
});

const LOWER = prescriptionView("STRENGTH_LOWER");
const WORK = workItems(LOWER).map((w) => w.item);
const everySet = () => WORK.flatMap((item) => Array.from({ length: item.sets }, (_, i) => result(item.prescriptionItemId, i + 1)));

describe("PARTIAL-01 — guidedRealisationOf", () => {
  it("Force: every prescribed work set performed → complete", () => {
    expect(guidedRealisationOf(LOWER, everySet())).toBe("complete");
  });

  it("Force: a work set missing, or marked « non réalisée » → partial", () => {
    expect(guidedRealisationOf(LOWER, everySet().slice(1))).toBe("partial");
    const all = everySet();
    expect(guidedRealisationOf(LOWER, [...all.slice(0, -1), { ...all.at(-1)!, done: false }])).toBe("partial");
    expect(guidedRealisationOf(LOWER, [result(WORK[0]!.prescriptionItemId, 1)])).toBe("partial"); // one set out of many
  });

  it("Force: a correction counts once, the active result decides", () => {
    const all = everySet();
    const first = all[0]!;
    const notDone = { ...first, id: "r0", done: false };
    expect(guidedRealisationOf(LOWER, [notDone, { ...first, id: "r1", supersedes_id: "r0" }, ...all.slice(1)])).toBe("complete");
    expect(guidedRealisationOf(LOWER, [{ ...first, id: "r0" }, { ...first, id: "r1", done: false, supersedes_id: "r0" }, ...all.slice(1)])).toBe("partial");
  });

  it("DH: every planned pass recorded → complete; fewer → partial", () => {
    const dh = prescriptionView("DH_TECHNICAL");
    const drill = mainDrill(dh)!;
    const passes = Array.from({ length: drill.passes }, (_, i) => result(drill.prescriptionItemId, i + 1));
    expect(guidedRealisationOf(dh, passes)).toBe("complete");
    expect(guidedRealisationOf(dh, passes.slice(0, 1))).toBe(drill.passes > 1 ? "partial" : "complete");
  });

  it("endurance and recovery: closing the session proves no full realisation → null (neutral), never complete or partial", () => {
    expect(guidedRealisationOf(prescriptionView("AEROBIC_BASE"), [])).toBeNull();
    expect(guidedRealisationOf(prescriptionView("REPLACE_TO_RECOVERY"), [])).toBeNull();
    expect(guidedRealisationOf(prescriptionView("TIME_RECOVERY_25"), [])).toBeNull();
  });

  it("ambiguous results (two active results for one set) are never arbitrated → null", () => {
    const all = everySet();
    expect(guidedRealisationOf(LOWER, [...all, { ...all[0]!, id: "dup" }])).toBeNull();
  });
});

// V2-PHYS-INTEGRATION-01 — PHYS-03: a power session is guided set by set like Force (strengthSets.isPowerPrescription),
// so PARTIAL-01 tells its realisation the same way: every explosive work set performed → complete; fewer → partial.

describe("PARTIAL-01 × PHYS-03 — a power session", () => {
  type Doc = { id: string; decisionId: string; schemaVersion: string; catalogVersion: string; structure: unknown };
  const doc = (phys03.finalPrescriptions as unknown as Record<string, Doc>).KEEP_POWER_INTERMEDIATE!;
  const decoded = decodeFinalPrescriptionV2({ id: doc.id, decisionId: doc.decisionId, schemaVersion: doc.schemaVersion, catalogVersion: doc.catalogVersion, structure: doc.structure });
  if (!decoded.ok) throw new Error(decoded.reason);
  const POWER = decoded.view;
  const explosive = workItems(POWER).map((w) => w.item);
  const all = () => explosive.flatMap((item) => Array.from({ length: item.sets }, (_, i) => result(item.prescriptionItemId, i + 1)));

  it("every explosive work set performed → complete; one missing → partial; none → partial (the server guard is POWER-GUARD-01's)", () => {
    expect(explosive).toHaveLength(4);
    expect(guidedRealisationOf(POWER, all())).toBe("complete");
    expect(guidedRealisationOf(POWER, all().slice(1))).toBe("partial");
    expect(guidedRealisationOf(POWER, [])).toBe("partial");
  });
});
